function resize(file,max){return new Promise(function(res,rej){var fr=new FileReader();fr.onerror=rej;fr.onload=function(){var im=new Image();im.onerror=rej;im.onload=function(){var w=im.width,h=im.height,k=Math.min(1,max/Math.max(w,h));var c=document.createElement('canvas');c.width=Math.round(w*k);c.height=Math.round(h*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',0.78));};im.src=fr.result;};fr.readAsDataURL(file);});}
function upload(files,kind,ref,by,msgEl){var out=[],i=0;files=Array.prototype.slice.call(files||[]);
 function next(){if(i>=files.length)return Promise.resolve(out);var f=files[i++];if(msgEl)msgEl.textContent='Uploading photo '+i+' of '+files.length+'...';
  return resize(f,1600).then(function(d){return post('cbs-snag-photo',{job:JOB,snag:ref,kind:kind,by:by,data:d});}).then(function(r){if(!r||!r.ok||!r.url)throw new Error('upload');out.push({u:r.url,at:new Date().toISOString(),by:by});return next();});}
 return next();}
function thumbs(list,rm){return '<div class="ph">'+list.map(function(p,i){return '<div class="pc"><a href="'+img(p.u)+'" target="_blank" rel="noopener"><img loading="lazy" src="'+img(p.u)+'" alt=""></a>'+(rm?'<button type="button" class="x" data-rm="'+i+'" title="Remove">&times;</button>':'')+'</div>';}).join('')+'</div>';}
function counts(){var c={open:0,fix:0,off:0};D.snags.forEach(function(r){var st=s(r.status)||ST_OPEN;if(st===ST_OFF)c.off++;else if(st===ST_FIX)c.fix++;else c.open++;});return c;}
