  h+='<div class="tools"><button class="btn" id="add">+ Add snag</button><button class="btn ghost" id="push">Send to ServiceM8</button><button class="btn ghost" id="rep">Snag report</button><button class="btn ghost" id="so" style="display:none">Sign off selected</button></div>';
