 V.forEach(function(r){var st=s(r.status)||ST_OPEN,B=pj(r.before_json),A=pj(r.after_json);
  h+='<div class="card" data-id="'+r.id+'"><div class="hd">'+(ADMIN&&st===ST_FIX?'<input type="checkbox" class="sel" value="'+r.id+'">':'')+'<div style="flex:1"><div class="t">'+e(lab(r))+stTag(r)+'</div>'
   +'<div class="m">'+e(r.description)+'</div>'
   +'<div class="m">'+e([r.assigned_to?'Assigned to '+r.assigned_to:'',r.due_on?'Due '+dmy(r.due_on):'',ADMIN&&r.pushed_at?'Sent '+dmy(r.pushed_at):'',ADMIN&&r.raised_by?'Raised by '+r.raised_by:''].filter(Boolean).join(' \u00b7 '))+'</div></div></div>';
