 app.querySelectorAll('[data-act]').forEach(function(b){b.onclick=function(){var id=b.closest('.card').getAttribute('data-id');var r=D.snags.filter(function(x){return String(x.id)===id;})[0];var a=b.getAttribute('data-act');
  if(a==='edit')editDlg(r);else if(a==='fix')fixDlg(r);else if(a==='signoff')signOff([r.id]);else if(a==='reopen')reopen(r);else if(a==='del')del(r);};});
}
function reload(){return fetch('/webhook/cbs-snags-data?job='+encodeURIComponent(JOB),{cache:'no-store'}).then(function(r){return r.json();}).then(function(d){D.snags=d.snags||[];render();}).catch(function(){location.reload();});}
function dlg(html){var o=document.createElement('div');o.className='ov';o.innerHTML='<div class="dlg">'+html+'</div>';document.body.appendChild(o);o.addEventListener('click',function(ev){if(ev.target===o)close();});function close(){o.remove();}o.close=close;return o;}
