 var o=dlg('<h2>'+(r?e(lab(r)):'New snag')+'</h2><label class="f">Area / location</label><input type="text" id="fa" list="dla" value="'+e(r&&r.area)+'" placeholder="e.g. Ground floor kitchen"><datalist id="dla">'+Object.keys(areas).map(function(a){return '<option value="'+e(a)+'">';}).join('')+'</datalist>'
