 function ph(){var el=o.querySelector('#fph');el.innerHTML=B.length?thumbs(B,true):'<div class="note">No photos yet.</div>';el.querySelectorAll('[data-rm]').forEach(function(x){x.onclick=function(){B.splice(Number(x.getAttribute('data-rm')),1);ph();};});}ph();
 o.querySelector('#fc').onclick=function(){o.close();};
